/// What an item of the history is.
@OptIn(ExperimentalSerializationApi::class)
@JsonClassDiscriminator("kind")
@Serializable
sealed class HistoryBody {
	@Serializable
	@SerialName("received")
	data class Received(val content: HistoryReceived): HistoryBody()
	@Serializable
	@SerialName("text")
	data class Text(val content: HistoryText): HistoryBody()
	@Serializable
	@SerialName("post")
	data class Post(val content: HistoryPost): HistoryBody()
	@Serializable
	@SerialName("mark")
	data class Mark(val content: HistoryMark): HistoryBody()
	@Serializable
	@SerialName("group")
	data class Group(val content: HistoryGroup): HistoryBody()
}

