@Serializable
data class HistoryItem (
	val key: String,
	val entries: List<Long>,
	val body: HistoryBody
)

@Serializable
data class HistoryLive (
	val id: String,
	val text: String
)

/// A wait in an agent's history: from its mark (`since`) until the next word brought it back (`until`, absent while it
